    # Find full separator rows and columns by their repeated color.
    row_sep = [r for r in range(h) if len(set(grid[r])) == 1]
    col_sep = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def bands(n, separators):
        result = []
        start = 0
        for i in separators:
            if start < i:
                result.append((start, i))
            start = i + 1
        if start < n:
            result.append((start, n))
        return result

    rb = bands(h, row_sep)
    cb = bands(w, col_sep)

    # Identify the panel background as the most frequent non-separator color.
    sep_colors = {grid[r][0] for r in row_sep} | {grid[0][c] for c in col_sep}
    counts = {}
    for r0, r1 in rb:
        for c0, c1 in cb:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    v = grid[r][c]
                    if v not in sep_colors:
                        counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    marker = next((v for v in counts if v != background), None)
    out = []
    for r0, r1 in rb:
        row = []
        for c0, c1 in cb:
            has_marker = marker is not None and any(
                grid[r][c] == marker
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            row.append(1 if has_marker else background)
        out.append(row)
    return out
