def transform(grid):
    h, w = len(grid), len(grid[0])

    # Separator rows and columns are solid lines.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def make_bands(n, separators):
        bands = []
        start = 0
        for i in separators:
            if start < i:
                bands.append((start, i))
            start = i + 1
        if start < n:
            bands.append((start, n))
        return bands

    row_bands = make_bands(h, sep_rows)
    col_bands = make_bands(w, sep_cols)

    separator_colors = {grid[r][0] for r in sep_rows}
    separator_colors.update(grid[0][c] for c in sep_cols)

    # The common panel color is the background; the less common color is
    # the object being counted.
    frequencies = {}
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    color = grid[r][c]
                    if color not in separator_colors:
                        frequencies[color] = frequencies.get(color, 0) + 1

    background = max(frequencies, key=frequencies.get)
    marker = min((color for color in frequencies if color != background),
                 key=lambda color: frequencies[color], default=None)

    result = []
    for r0, r1 in row_bands:
        row = []
        for c0, c1 in col_bands:
            count = sum(
                grid[r][c] == marker
                for r in range(r0, r1)
                for c in range(c0, c1)
            ) if marker is not None else 0
            row.append(1 if count == 2 else background)
        result.append(row)
    return result
